-- Heroes of Horror feat prerequisites.
-- Tainted feats also apply the book-wide rule that only nongood creatures suffering the required taint may acquire them.
WITH desired(slug,expression,explanation) AS (VALUES
  ('archivist-of-nature','{"version":1,"condition":{"kind":"class_feature","classFeatureId":"hoh-class-feature-archivist-dark-knowledge"}}','Dark knowledge class feature.'),
  ('blood-calls-to-blood','{"version":1,"condition":{"kind":"all","conditions":[{"kind":"custom","description":"Spontaneous arcane spellcaster.","extension":{"key":"dnd35.prerequisite.spontaneous-arcane-caster","version":1,"parameters":{}}},{"kind":"custom","description":"A fiend appears in the character''s ancestry.","extension":{"key":"dnd35.hoh.prerequisite.fiend-ancestor","version":1,"parameters":{}}}]}}','Spontaneous arcane caster; fiend ancestor.'),
  ('corrupt-spell-focus','{"version":1,"condition":{"kind":"alignment","allowed":["LN","N","CN","LE","NE","CE"]}}','Nongood alignment.'),
  ('greater-corrupt-spell-focus','{"version":1,"condition":{"kind":"all","conditions":[{"kind":"alignment","allowed":["LN","N","CN","LE","NE","CE"]},{"kind":"feat","featId":"hoh-feat-corrupt-spell-focus"}]}}','Nongood alignment; Corrupt Spell Focus.'),
  ('disease-immunity','{"version":1,"condition":{"kind":"ability","ability":"con","minimum":13}}','Constitution 13.'),
  ('draconic-archivist','{"version":1,"condition":{"kind":"class_feature","classFeatureId":"hoh-class-feature-archivist-dark-knowledge"}}','Dark knowledge class feature.'),
  ('oneiromancy','{"version":1,"condition":{"kind":"all","conditions":[{"kind":"feat","featId":"hoh-feat-dreamtelling"},{"kind":"custom","description":"Ability to cast spells of any sort.","extension":{"key":"dnd35.prerequisite.spellcaster","version":1,"parameters":{}}}]}}','Dreamtelling; ability to cast spells of any sort.'),
  ('improved-oneiromancy','{"version":1,"condition":{"kind":"all","conditions":[{"kind":"feat","featId":"hoh-feat-oneiromancy"},{"kind":"feat","featId":"hoh-feat-dreamtelling"},{"kind":"custom","description":"Ability to cast spells of any sort.","extension":{"key":"dnd35.prerequisite.spellcaster","version":1,"parameters":{}}}]}}','Oneiromancy; Dreamtelling; spellcaster. Table 5-9 lists Dreamtelling; the feat-description line in the supplied PDF appears as “Dreamcasting,” so the table requirement is preserved here without silently inventing a missing feat.'),
  ('font-of-life','{"version":1,"condition":{"kind":"custom","description":"Living creature.","extension":{"key":"dnd35.prerequisite.living-creature","version":1,"parameters":{}}}}','Living creature.'),
  ('haunting-melody','{"version":1,"condition":{"kind":"all","conditions":[{"kind":"class_feature","classFeatureId":"phb-class-feature-bard-bardic-music"},{"kind":"skill_ranks","skillId":"phb-skill-perform","minimum":9}]}}','Bardic music class feature; Perform 9 ranks.'),
  ('pure-soul','{"version":1,"condition":{"kind":"all","conditions":[{"kind":"alignment","allowed":["LG","NG","CG","LN","N","CN"]},{"kind":"custom","description":"No taint.","extension":{"key":"dnd35.hoh.prerequisite.taint","version":1,"parameters":{"maximum":0}}}]}}','Non-evil alignment; no taint.'),
  ('spirit-sense','{"version":1,"condition":{"kind":"all","conditions":[{"kind":"ability","ability":"wis","minimum":12},{"kind":"custom","description":"Must have had a near-death experience by falling below 0 hit points.","extension":{"key":"dnd35.hoh.prerequisite.near-death-experience","version":1,"parameters":{}}}]}}','Wisdom 12; near-death experience (fallen below 0 hit points).'),
  ('unnatural-will','{"version":1,"condition":{"kind":"all","conditions":[{"kind":"ability","ability":"cha","minimum":12},{"kind":"feat","featId":"phb-feat-iron-will"}]}}','Charisma 12; Iron Will.'),

  ('corrupt-arcana','{"version":1,"condition":{"kind":"all","conditions":[{"kind":"alignment","allowed":["LN","N","CN","LE","NE","CE"]},{"kind":"custom","description":"Spontaneous spellcaster.","extension":{"key":"dnd35.prerequisite.spontaneous-caster","version":1,"parameters":{}}},{"kind":"custom","description":"Mild or greater depravity.","extension":{"key":"dnd35.hoh.prerequisite.taint","version":1,"parameters":{"score":"depravity","minimumDegree":"mild"}}}]}}','Spontaneous caster; mild depravity; tainted-feat nongood requirement.'),
  ('eldritch-corruption','{"version":1,"condition":{"kind":"all","conditions":[{"kind":"alignment","allowed":["LN","N","CN","LE","NE","CE"]},{"kind":"custom","description":"Any one metamagic feat.","extension":{"key":"dnd35.prerequisite.feat-category","version":1,"parameters":{"category":"metamagic","minimum":1}}},{"kind":"custom","description":"Moderate or greater depravity.","extension":{"key":"dnd35.hoh.prerequisite.taint","version":1,"parameters":{"score":"depravity","minimumDegree":"moderate"}}}]}}','Any metamagic feat; moderate depravity; tainted-feat nongood requirement.'),
  ('forbidden-lore','{"version":1,"condition":{"kind":"all","conditions":[{"kind":"alignment","allowed":["LN","N","CN","LE","NE","CE"]},{"kind":"custom","description":"Bardic knowledge or lore class feature.","extension":{"key":"dnd35.hoh.prerequisite.lore-feature","version":1,"parameters":{}}},{"kind":"custom","description":"Mild or greater depravity.","extension":{"key":"dnd35.hoh.prerequisite.taint","version":1,"parameters":{"score":"depravity","minimumDegree":"mild"}}}]}}','Bardic knowledge or lore class feature; mild depravity; tainted-feat nongood requirement.'),
  ('lunatic-insight','{"version":1,"condition":{"kind":"all","conditions":[{"kind":"alignment","allowed":["LN","N","CN","LE","NE","CE"]},{"kind":"custom","description":"Mild or greater depravity.","extension":{"key":"dnd35.hoh.prerequisite.taint","version":1,"parameters":{"score":"depravity","minimumDegree":"mild"}}}]}}','Mild depravity; tainted-feat nongood requirement.'),
  ('mad-faith','{"version":1,"condition":{"kind":"all","conditions":[{"kind":"alignment","allowed":["LN","N","CN","LE","NE","CE"]},{"kind":"spell_level_access","minimum":1,"tradition":"divine"},{"kind":"custom","description":"Mild or greater depravity.","extension":{"key":"dnd35.hoh.prerequisite.taint","version":1,"parameters":{"score":"depravity","minimumDegree":"mild"}}}]}}','Ability to cast 1st-level divine spells; mild depravity; tainted-feat nongood requirement.'),
  ('surge-of-malevolence','{"version":1,"condition":{"kind":"all","conditions":[{"kind":"alignment","allowed":["LN","N","CN","LE","NE","CE"]},{"kind":"custom","description":"Mild or greater taint.","extension":{"key":"dnd35.hoh.prerequisite.taint","version":1,"parameters":{"minimumDegree":"mild"}}}]}}','Mild taint; tainted-feat nongood requirement.'),
  ('debilitating-spell','{"version":1,"condition":{"kind":"all","conditions":[{"kind":"alignment","allowed":["LN","N","CN","LE","NE","CE"]},{"kind":"feat","featId":"hoh-feat-surge-of-malevolence"},{"kind":"custom","description":"Moderate or greater taint.","extension":{"key":"dnd35.hoh.prerequisite.taint","version":1,"parameters":{"minimumDegree":"moderate"}}}]}}','Surge of Malevolence; moderate taint; tainted-feat nongood requirement.'),
  ('debilitating-strike','{"version":1,"condition":{"kind":"all","conditions":[{"kind":"alignment","allowed":["LN","N","CN","LE","NE","CE"]},{"kind":"feat","featId":"hoh-feat-surge-of-malevolence"},{"kind":"custom","description":"Moderate or greater taint.","extension":{"key":"dnd35.hoh.prerequisite.taint","version":1,"parameters":{"minimumDegree":"moderate"}}}]}}','Surge of Malevolence; moderate taint; tainted-feat nongood requirement.'),
  ('tainted-fury','{"version":1,"condition":{"kind":"all","conditions":[{"kind":"alignment","allowed":["LN","N","CN","LE","NE","CE"]},{"kind":"ability","ability":"con","minimum":13},{"kind":"custom","description":"Moderate or greater corruption.","extension":{"key":"dnd35.hoh.prerequisite.taint","version":1,"parameters":{"score":"corruption","minimumDegree":"moderate"}}}]}}','Constitution 13; moderate corruption; tainted-feat nongood requirement.'),

  ('touch-of-taint','{"version":1,"condition":{"kind":"custom","description":"A natural attack that deals ability damage (including poison), ability drain, or energy drain.","extension":{"key":"dnd35.hoh.prerequisite.draining-natural-attack","version":1,"parameters":{}}}}','Natural attack that deals ability damage, ability drain, or energy drain.'),

  ('willing-deformity','{"version":1,"condition":{"kind":"all","conditions":[{"kind":"alignment","allowed":["LE","NE","CE"]},{"kind":"custom","description":"Intelligent creature, as required for vile feats.","extension":{"key":"dnd35.prerequisite.intelligent-creature","version":1,"parameters":{}}}]}}','Evil alignment; intelligent creature (vile feat rule).'),
  ('deformity-skin','{"version":1,"condition":{"kind":"all","conditions":[{"kind":"alignment","allowed":["LE","NE","CE"]},{"kind":"feat","featId":"hoh-feat-willing-deformity"}]}}','Evil alignment; Willing Deformity.'),
  ('deformity-tall','{"version":1,"condition":{"kind":"all","conditions":[{"kind":"alignment","allowed":["LE","NE","CE"]},{"kind":"feat","featId":"hoh-feat-willing-deformity"},{"kind":"custom","description":"Medium size.","extension":{"key":"dnd35.prerequisite.size","version":1,"parameters":{"size":"medium"}}}]}}','Evil alignment; Willing Deformity; Medium size.'),
  ('deformity-teeth','{"version":1,"condition":{"kind":"all","conditions":[{"kind":"alignment","allowed":["LE","NE","CE"]},{"kind":"feat","featId":"hoh-feat-willing-deformity"}]}}','Evil alignment; Willing Deformity.'),
  ('deformity-tongue','{"version":1,"condition":{"kind":"all","conditions":[{"kind":"alignment","allowed":["LE","NE","CE"]},{"kind":"feat","featId":"hoh-feat-willing-deformity"}]}}','Evil alignment; Willing Deformity.')
)
INSERT INTO dnd35_feat_prerequisites (feat_id,expression,explanation)
SELECT f.id,d.expression,d.explanation
FROM desired d
JOIN dnd35_feats f ON f.slug=d.slug
JOIN dnd35_sources s ON s.id=f.source_id
WHERE s.slug='heroes-of-horror-3-5' AND f.owner_user_id IS NULL
ON CONFLICT(feat_id) DO UPDATE SET expression=excluded.expression,explanation=excluded.explanation;
